//! The theme palettes as `gdk::RGBA`s for custom-drawn widgets (G§3.14):
//! GTK can't look a CSS custom property up from code. One [`Palette`] per
//! theme with every color token, plus the eight take colors and their
//! tints in cycle order (`view::format::take_color` indexes them); the
//! only file in `src/` that holds color values.
//!
//! Generated from design/tokens/qrec-tokens.json by
//! crates/qrec-gui/tests/tokens.rs (QREC_UPDATE_TOKENS=1 cargo test -p
//! qrec-gui --test tokens). Do not edit: change the variable in
//! design/qrec.pen and regenerate.

use gtk::gdk;
use qrec_core::config::Theme as ThemeId;

/// A theme's colors for drawing: one field per color token (`-` → `_`).
#[derive(Debug, Clone, PartialEq)]
pub struct Palette {
    pub accent: gdk::RGBA,
    pub accent_2: gdk::RGBA,
    pub accent_2_20: gdk::RGBA,
    pub accent_text: gdk::RGBA,
    pub bg: gdk::RGBA,
    pub bg_55: gdk::RGBA,
    pub border: gdk::RGBA,
    pub border_strong: gdk::RGBA,
    pub caret: gdk::RGBA,
    pub disabled_text: gdk::RGBA,
    pub field: gdk::RGBA,
    pub focus_ring: gdk::RGBA,
    pub ghost_fill: gdk::RGBA,
    pub hatch_stripe: gdk::RGBA,
    pub hover: gdk::RGBA,
    pub keycap: gdk::RGBA,
    pub meter_green: gdk::RGBA,
    pub meter_red: gdk::RGBA,
    pub meter_yellow: gdk::RGBA,
    pub mud: gdk::RGBA,
    pub mud_bubble: gdk::RGBA,
    pub muted: gdk::RGBA,
    pub muted_20: gdk::RGBA,
    pub muted_40: gdk::RGBA,
    pub playhead: gdk::RGBA,
    pub pressed: gdk::RGBA,
    pub project_canvas: gdk::RGBA,
    pub raised: gdk::RGBA,
    pub record: gdk::RGBA,
    pub record_25: gdk::RGBA,
    pub record_glow: gdk::RGBA,
    pub record_text: gdk::RGBA,
    pub scrim: gdk::RGBA,
    pub scrim_strong: gdk::RGBA,
    pub selected: gdk::RGBA,
    pub shadow: gdk::RGBA,
    pub shadow_e1: gdk::RGBA,
    pub shadow_e2: gdk::RGBA,
    pub shadow_e2_contact: gdk::RGBA,
    pub shadow_e3: gdk::RGBA,
    pub snap_guide: gdk::RGBA,
    pub success: gdk::RGBA,
    pub surface: gdk::RGBA,
    pub take_donkey: gdk::RGBA,
    pub take_donkey_tint: gdk::RGBA,
    pub take_dragon: gdk::RGBA,
    pub take_dragon_tint: gdk::RGBA,
    pub take_fairy: gdk::RGBA,
    pub take_fairy_tint: gdk::RGBA,
    pub take_ginger: gdk::RGBA,
    pub take_ginger_tint: gdk::RGBA,
    pub take_lily: gdk::RGBA,
    pub take_lily_tint: gdk::RGBA,
    pub take_moss: gdk::RGBA,
    pub take_moss_tint: gdk::RGBA,
    pub take_mud: gdk::RGBA,
    pub take_mud_tint: gdk::RGBA,
    pub take_onion: gdk::RGBA,
    pub take_onion_tint: gdk::RGBA,
    pub text: gdk::RGBA,
    pub text_35: gdk::RGBA,
    pub text_on_accent: gdk::RGBA,
    pub text_on_accent_45: gdk::RGBA,
    pub text_on_record: gdk::RGBA,
    pub text_on_record_45: gdk::RGBA,
    pub video_scrim: gdk::RGBA,
    pub video_text: gdk::RGBA,
    pub video_text_20: gdk::RGBA,
    pub warning: gdk::RGBA,
    pub warning_16: gdk::RGBA,
    pub warning_20: gdk::RGBA,
    pub warning_text: gdk::RGBA,
    pub wave: gdk::RGBA,
    pub wave_dim: gdk::RGBA,
    pub wood: gdk::RGBA,
    /// The eight take colors: moss, donkey, onion, mud, lily, ginger,
    /// dragon, fairy (`view::format::take_color` indexes them).
    pub take: [gdk::RGBA; 8],
    /// Their tints (the take color at 12 %: audio lane segments).
    pub take_tint: [gdk::RGBA; 8],
}

impl Default for Palette {
    fn default() -> Self {
        SWAMP_NIGHT
    }
}

impl Palette {
    /// The palette of theme `id`.
    pub fn for_theme(id: ThemeId) -> Palette {
        match id {
            ThemeId::SwampNight => SWAMP_NIGHT,
            ThemeId::SwampDay => SWAMP_DAY,
            ThemeId::DragonsKeep => DRAGONS_KEEP,
            ThemeId::OgreMode => OGRE_MODE,
        }
    }

    /// The color of token `name` (as `qrec-tokens.json` names it), for
    /// templates that take token names (the art).
    pub fn color(&self, name: &str) -> Option<gdk::RGBA> {
        Some(match name {
            "accent" => self.accent,
            "accent-2" => self.accent_2,
            "accent-2-20" => self.accent_2_20,
            "accent-text" => self.accent_text,
            "bg" => self.bg,
            "bg-55" => self.bg_55,
            "border" => self.border,
            "border-strong" => self.border_strong,
            "caret" => self.caret,
            "disabled-text" => self.disabled_text,
            "field" => self.field,
            "focus-ring" => self.focus_ring,
            "ghost-fill" => self.ghost_fill,
            "hatch-stripe" => self.hatch_stripe,
            "hover" => self.hover,
            "keycap" => self.keycap,
            "meter-green" => self.meter_green,
            "meter-red" => self.meter_red,
            "meter-yellow" => self.meter_yellow,
            "mud" => self.mud,
            "mud-bubble" => self.mud_bubble,
            "muted" => self.muted,
            "muted-20" => self.muted_20,
            "muted-40" => self.muted_40,
            "playhead" => self.playhead,
            "pressed" => self.pressed,
            "project-canvas" => self.project_canvas,
            "raised" => self.raised,
            "record" => self.record,
            "record-25" => self.record_25,
            "record-glow" => self.record_glow,
            "record-text" => self.record_text,
            "scrim" => self.scrim,
            "scrim-strong" => self.scrim_strong,
            "selected" => self.selected,
            "shadow" => self.shadow,
            "shadow-e1" => self.shadow_e1,
            "shadow-e2" => self.shadow_e2,
            "shadow-e2-contact" => self.shadow_e2_contact,
            "shadow-e3" => self.shadow_e3,
            "snap-guide" => self.snap_guide,
            "success" => self.success,
            "surface" => self.surface,
            "take-donkey" => self.take_donkey,
            "take-donkey-tint" => self.take_donkey_tint,
            "take-dragon" => self.take_dragon,
            "take-dragon-tint" => self.take_dragon_tint,
            "take-fairy" => self.take_fairy,
            "take-fairy-tint" => self.take_fairy_tint,
            "take-ginger" => self.take_ginger,
            "take-ginger-tint" => self.take_ginger_tint,
            "take-lily" => self.take_lily,
            "take-lily-tint" => self.take_lily_tint,
            "take-moss" => self.take_moss,
            "take-moss-tint" => self.take_moss_tint,
            "take-mud" => self.take_mud,
            "take-mud-tint" => self.take_mud_tint,
            "take-onion" => self.take_onion,
            "take-onion-tint" => self.take_onion_tint,
            "text" => self.text,
            "text-35" => self.text_35,
            "text-on-accent" => self.text_on_accent,
            "text-on-accent-45" => self.text_on_accent_45,
            "text-on-record" => self.text_on_record,
            "text-on-record-45" => self.text_on_record_45,
            "video-scrim" => self.video_scrim,
            "video-text" => self.video_text,
            "video-text-20" => self.video_text_20,
            "warning" => self.warning,
            "warning-16" => self.warning_16,
            "warning-20" => self.warning_20,
            "warning-text" => self.warning_text,
            "wave" => self.wave,
            "wave-dim" => self.wave_dim,
            "wood" => self.wood,
            _ => return None,
        })
    }
}

/// A color from its 8-bit channels.
const fn rgba(red: u8, green: u8, blue: u8, alpha: u8) -> gdk::RGBA {
    gdk::RGBA::new(
        red as f32 / 255.0,
        green as f32 / 255.0,
        blue as f32 / 255.0,
        alpha as f32 / 255.0,
    )
}

